L(OA21, 1,
  "Este cuaderno, lápiz y los textos breves de cada ejercicio.",
  "Aprenderé a reconocer qué sustantivo reemplaza un pronombre en un texto.",
  ["Sé reconocer sustantivos y artículos.", "Sé leer textos cortos de varias oraciones."],
  ["Un pronombre es una palabra que reemplaza a un sustantivo o a un grupo de palabras. Algunos pronombres son yo, tú, él, ella, nosotros, nosotras, ellos y ellas. También lo, la, los y las pueden reemplazar un sustantivo: «Veo el loro» se dice «Lo veo».",
   "La persona o cosa a la que se refiere el pronombre se llama referente. En «Sofía llegó. Ella saludó», el pronombre es ella y el referente es Sofía. El pronombre evita repetir el nombre.",
   "Para encontrar el referente, busca hacia atrás en el texto un sustantivo que coincida en género y número. «Ellas» reemplaza a varias personas o cosas femeninas, como «mis primas». «Él» reemplaza a un solo sustantivo masculino, como «el gato»."],
  [("pronombre", "palabra que reemplaza a un sustantivo"), ("referente", "lo que reemplaza el pronombre"), ("él, ella", "pronombres para una persona o cosa, masculino o femenino"), ("ellos, ellas", "pronombres para varias personas o cosas"), ("nosotros", "yo y otra u otras personas")],
  [("Encontrar el referente", "Lee: «Mis primas viven lejos. Ellas me visitan en verano». ¿A quiénes reemplaza «ellas»?", ["Busco hacia atrás.", "Ellas es plural y femenino.", "Concuerda con mis primas."], "A mis primas"),
   ("Reconocer un pronombre", "En «Pedro canta. Él toca la guitarra», ¿cuál es el pronombre y a quién reemplaza?", ["El pronombre reemplaza un nombre.", "Él es masculino singular.", "Reemplaza a Pedro."], "Él reemplaza a Pedro")],
  [("Pensar que el pronombre reemplaza cualquier palabra.", "Reemplaza sustantivos o grupos de palabras.", "Busca qué sustantivo reemplaza."), ("Elegir un referente que no concuerda.", "Ellas no reemplaza a un solo niño.", "Revisa género y número.")],
  ([E("En «Pedro canta. Él toca la guitarra», ¿qué palabra es el pronombre?", "Él", "Reemplaza a Pedro."),
    E("¿A quién reemplaza «ella» en «Sofía llegó. Ella saludó»?", "A Sofía", "Ella reemplaza a la persona nombrada antes."),
    E("¿«Ellos» reemplaza a un solo niño o a varios niños?", "A varios niños", "Ellos es plural.")],
   [E("«Mis primas viven lejos. Ellas me visitan en verano». ¿A quién reemplaza «ellas»?", "A mis primas", "Es femenino plural."),
    E("«El gato duerme. Él ronronea». ¿Qué sustantivo reemplaza «él»?", "El gato", "Es masculino singular."),
    E("Para reemplazar «Luis y yo», ¿qué pronombre sirve: nosotros o ellos?", "Nosotros", "Incluye a quien habla.")],
   [E("En «Ana y Tomás juegan. Ellos ríen», ¿a quiénes reemplaza «ellos»?", "A Ana y Tomás", "Reemplaza a las dos personas."),
    E("Completa con un pronombre: «María canta bien. ___ canta bien».", "Ella", "María es femenino singular."),
    E("Completa con un pronombre: «Los perros ladran. ___ ladran».", "Ellos", "Los perros es masculino plural.")],
   [E("En «La profesora entró. Ella saludó», ¿puede «ella» reemplazar a «los niños»? Responde sí o no y por qué.", "No, porque los niños es plural y masculino", "Ella es singular y femenino."),
    E("¿«Yo» siempre reemplaza a la persona que habla o a la que escucha?", "A la que habla", "Yo se refiere a quien dice la oración.")],
   [E("Lee: «Nicolás y su amigo salieron. Ellos fueron al parque». Escribe el referente de «ellos».", "Nicolás y su amigo", "Son dos personas masculinas."),
    E("Lee: «Mi vecina tiene un loro. Ella lo cuida mucho». ¿A quién reemplaza «lo»?", "Al loro", "Lo reemplaza al sustantivo masculino loro.")]),
  [E("Un letrero dice: «Los niños de segundo juegan en el patio. Ellos usan la cancha por la mañana». ¿A quiénes reemplaza «ellos»?", "A los niños de segundo", "Es masculino plural.")],
  [E("¿Qué hace un pronombre?", "Reemplaza a un sustantivo", "Así se evita repetirlo."),
   E("¿Cómo se llama lo que reemplaza el pronombre?", "Referente", "Es la persona o cosa a la que se refiere."),
   E("Para encontrar el referente, ¿miro hacia atrás o hacia adelante del texto?", "Hacia atrás", "El sustantivo suele aparecer antes.")],
  ("Lee este texto: «Los hermanos Pía y Mateo hicieron una torta. Ellos usaron huevos y harina. Pía la decoró con frutillas. Mateo la llevó a la mesa. Él la cortó en ocho trozos». Escribe a quién o a qué se refiere cada pronombre: ellos, la (en «Pía la decoró»), él.", "Ellos: Pía y Mateo. La: la torta. Él: Mateo.", ["identifica tres referentes", "justifica con género y número", "escribe cada referente"], ["lista de tres pronombres con su referente"], ["elegir un referente que no concuerda", "confundir ella con Pía"], "Lee tu lista a otra persona y revisen juntos cada pronombre."),
  "Busca en un texto un pronombre y subraya a qué se refiere.",
  "Escribe tres oraciones con los pronombres él, ella y ellos, cada una con su referente.")

L(OA21, 2,
  "Este cuaderno, lápiz y los textos de cada ejercicio.",
  "Aprenderé a evitar repeticiones innecesarias reemplazando sustantivos por pronombres.",
  ["Sé reconocer el referente de un pronombre.", "Sé que repetir mucho una palabra cansa al lector."],
  ["Si repites el mismo nombre en cada oración, el texto suena pesado. «Luis come. Luis bebe. Luis lee» repite tres veces el nombre. Puedes usar un pronombre: «Luis come. Él bebe y lee».",
   "A veces no necesitas escribir ni el nombre ni el pronombre. En español puedes dejar el sujeto sin escribirlo cuando se entiende: «Luis come. Bebe y lee». También puedes usar lo, la, los o las en lugar de un sustantivo: «Compré pan. Lo comí».",
   "Cuida que el pronombre concuerde con el sustantivo. Para una niña usas ella, para unos libros usas los o ellos, y para una mesa usas la o ella. Y revisa que el lector entienda a quién te refieres."],
  [("repetición", "usar muchas veces la misma palabra"), ("pronombre", "palabra que reemplaza a un sustantivo"), ("lo, la", "pronombres para una cosa o persona en singular"), ("los, las", "pronombres para varias cosas o personas"), ("sujeto", "quien hace la acción")],
  [("Evitar repetir un nombre", "Mejora: «Sofía abrió la caja. Sofía vio un regalo. Sofía sonrió».", ["Sofía se repite tres veces.", "Dejo el nombre una vez.", "Después uso ella o dejo el sujeto sin escribir."], "«Sofía abrió la caja. Ella vio un regalo y sonrió»"),
   ("Reemplazar con lo", "Mejora: «Compré pan. Comí el pan».", ["El pan se repite.", "El pan es masculino singular.", "Lo reemplaza a el pan."], "«Compré pan. Lo comí»")],
  [("Reemplazar «la pelota» por «él».", "Pelota es femenino.", "Usa ella o la."), ("Reemplazar todos los nombres siempre.", "El lector puede confundirse.", "Mantén el nombre cuando aclare.")],
  ([E("En «Luis come. Luis bebe. Luis lee», ¿qué palabra se repite?", "Luis", "Aparece tres veces."),
    E("Repetir mucho el mismo nombre, ¿hace el texto más pesado o más ligero?", "Más pesado", "Cansa al lector."),
    E("Para no repetir «Sofía», ¿qué pronombre sirve: ella o ellos?", "Ella", "Sofía es singular y femenino.")],
   [E("Elige la mejor versión: A) «Ana tiene un perro. Ana pasea al perro». B) «Ana tiene un perro. Lo pasea». ¿Cuál evita la repetición?", "B", "Lo reemplaza a el perro."),
    E("En «Mis amigos llegaron. Mis amigos se sentaron», ¿qué pronombre reemplaza al segundo «mis amigos»?", "Ellos", "Es masculino plural."),
    E("En «Compré pan. Comí el pan», ¿qué pronombre reemplaza a «el pan»?", "Lo", "Pan es masculino singular.")],
   [E("Completa: «Mi hermana es alta. ___ juega básquetbol». Elige ella o él.", "Ella", "Hermana es femenino."),
    E("Completa: «El gato bebe leche. ___ bebe con ganas». Elige él o ella.", "Él", "Gato es masculino."),
    E("Completa: «Vi a las niñas. ___ vi en la plaza». Elige las o los.", "Las", "Niñas es femenino plural.")],
   [E("¿Es siempre mejor cambiar todos los nombres por pronombres? Responde sí o no y por qué.", "No, porque a veces el lector se confunde", "A veces conviene repetir el nombre."),
    E("Un niño reemplazó «la pelota» por «él» en una oración. ¿Por qué no concuerda?", "Porque pelota es femenina", "Corresponde ella o la.")],
   [E("Texto: «Tomás tiene un perro. Tomás lava al perro cada semana. Tomás ama al perro». ¿Qué grupo de palabras reemplazas por «lo» en la segunda oración: «al perro» o «Tomás»?", "Al perro", "Se puede decir: Tomás lo lava."),
    E("Completa: «Rosa compró flores. ___ puso en un jarrón». Elige las o los.", "Las", "Flores es femenino plural.")]),
  [E("Escribes: «La profesora llegó. La profesora saludó. La profesora comenzó la clase». ¿Qué pronombre usas para no repetir: ella o ellos?", "Ella", "Profesora es femenino singular.")],
  [E("¿Para qué reemplazo un sustantivo por un pronombre?", "Para no repetir", "Así se evitan las repeticiones."),
   E("¿Qué debe coincidir entre el pronombre y el sustantivo?", "Género y número", "Deben concordar entre sí."),
   E("En «Compré manzanas. Las comí», ¿qué reemplaza «las»?", "Las manzanas", "Es femenino plural.")],
  ("Reescribe sin repeticiones: «Camila compró un cuaderno. Camila escribió en el cuaderno. Camila guardó el cuaderno en la mochila». Debes usar al menos un «ella» y un «lo». Luego lee tu texto y comprueba que se entiende.", "«Camila compró un cuaderno. Ella lo usó para escribir y después lo guardó en la mochila».", ["quita las repeticiones", "usa pronombres que concuerdan", "se entiende el texto"], ["texto reescrito"], ["usar el pronombre equivocado", "dejar tres veces el nombre"], "Lee tu texto en voz alta y pregunta si suena natural."),
  "Cuenta una acción tuya de hoy en tres oraciones sin repetir tu nombre ni una palabra.",
  "Escribe un párrafo de cuatro oraciones con dos pronombres y comprueba su referente.")

L(OA21, 3,
  "Este cuaderno, lápiz y los textos de cada ejercicio.",
  "Aprenderé a detectar cuando un pronombre puede referirse a más de un sustantivo y a aclarar el texto.",
  ["Sé usar pronombres para no repetir.", "Sé encontrar el referente."],
  ["A veces un pronombre puede referirse a dos personas o cosas, y el lector no sabe a cuál. Eso es un referente ambiguo. En «Ana habló con Sofía. Ella sonrió», ella puede ser Ana o Sofía.",
   "Pasa cuando hay dos sustantivos que coinciden en género y número. Si dos niñas aparecen antes del pronombre ella, hay confusión. En cambio, «Ema vio a Raúl. Él sonrió» no es ambiguo, porque él solo puede ser Raúl.",
   "Para arreglar la ambigüedad, repite el nombre o cambia la oración. «Ana habló con Sofía. Sofía sonrió» es claro. Cuando escribas, revisa cada pronombre y pregúntate si solo puede referirse a una persona o cosa."],
  [("ambiguo", "que puede entenderse de dos o más formas"), ("referente", "lo que reemplaza el pronombre"), ("aclarar", "dejar algo claro"), ("coincidir", "ser igual en género y número"), ("confusión", "no entender bien")],
  [("Detectar ambigüedad", "«Juan y Pablo jugaron. Él ganó». ¿Es claro quién ganó?", ["Hay dos niños.", "Él puede ser Juan o Pablo.", "No es claro."], "No, él puede ser Juan o Pablo"),
   ("Aclarar", "Aclara: «Ana habló con Sofía. Ella sonrió». Quien sonrió fue Sofía.", ["Hay dos personas femeninas.", "Reemplazo ella por el nombre.", "Así no hay duda."], "«Ana habló con Sofía. Sofía sonrió»")],
  [("Creer que siempre se entiende.", "Para quien escribe es claro, para el lector no.", "Pregunta si el pronombre puede ser más de uno."), ("Cambiar todos los nombres por pronombres.", "Aumenta la ambigüedad.", "Repite el nombre si hace falta.")],
  ([E("En «Ana habló con Sofía. Ella sonrió», ¿a cuántas personas puede referirse «ella»?", "A dos", "Puede ser Ana o Sofía."),
    E("Un referente ambiguo es el que se entiende de…", "Varias formas", "No es claro."),
    E("En «Luis corre. Él gana», ¿es claro a quién se refiere «él»? Responde sí o no.", "Sí", "Solo hay una persona.")],
   [E("«Juan y Pablo jugaron. Él ganó». ¿Es claro quién ganó? Responde sí o no.", "No", "Él puede ser Juan o Pablo."),
    E("«La niña abrazó a su perra. Ella saltó». ¿Es ambiguo? Responde sí o no.", "Sí", "Niña y perra son femeninas."),
    E("«Ema vio a Raúl. Él sonrió». ¿Es ambiguo? Responde sí o no.", "No", "Él solo puede ser Raúl.")],
   [E("Camila habló con Sofía y quien estaba contenta era Sofía. ¿Cuál escribes: «Ella estaba contenta» o «Sofía estaba contenta»?", "Sofía estaba contenta", "El nombre evita la duda."),
    E("¿Cuál oración es clara? A) «Tomás saludó a Mateo y él sonrió». B) «Tomás saludó a Mateo y Mateo sonrió».", "B", "Repite el nombre para aclarar."),
    E("«Los perros siguieron a los gatos. Ellos corrieron rápido». ¿Es claro quiénes corrieron? Responde sí o no.", "No", "Ellos puede ser perros o gatos.")],
   [E("Para arreglar una ambigüedad, ¿repito el nombre o pongo otro pronombre?", "Repito el nombre", "El nombre deja claro el referente."),
    E("En un texto hay dos niños. Si usas «él», ¿hay riesgo de ambigüedad? Responde sí o no.", "Sí", "Él puede ser cualquiera de los dos.")],
   [E("Lee: «Rosa llamó a Elena. Ella tenía fiebre». Quien tenía fiebre era Elena. Escribe la oración que aclara.", "Elena tenía fiebre", "Se usa el nombre en lugar del pronombre."),
    E("Lee: «Luis y Mario fueron al cine. Él compró palomitas». Fue Mario quien las compró. Escribe cómo aclaras.", "Mario compró palomitas", "El nombre elimina la duda.")]),
  [E("Una nota de tu curso dice: «La profesora habló con la directora. Ella autorizó la salida». ¿Se sabe quién autorizó? Responde sí o no.", "No", "Ella puede ser la profesora o la directora.")],
  [E("¿Cuándo hay ambigüedad?", "Cuando el pronombre puede referirse a más de uno", "Hay dos sustantivos posibles."),
   E("¿Cómo se aclara una oración ambigua?", "Repitiendo el nombre", "Así queda claro."),
   E("¿El pronombre ayuda si hay dos niñas y escribo «ella»? Responde sí o no.", "No", "Podría ser cualquiera de las dos.")],
  ("Lee: «Lola fue a visitar a Marta. Ella le regaló una planta. Después, ella la regó». Hay dos personas femeninas. Escribe una versión clara usando los nombres donde hace falta. Considera que Lola regaló la planta y Marta la regó.", "«Lola fue a visitar a Marta. Lola le regaló una planta. Después, Marta la regó».", ["usa los nombres donde hay ambigüedad", "el texto se entiende", "mantiene el sentido"], ["texto reescrito"], ["dejar «ella» dos veces", "confundir quién hizo cada acción"], "Pide a otra persona que diga quién hizo cada acción."),
  "Busca en un cuento una oración con dos personajes y un pronombre; ¿es claro?",
  "Escribe una oración ambigua y su versión aclarada.")

L(OA21, 4,
  "Este cuaderno, lápiz y los textos de cada ejercicio.",
  "Aprenderé a alternar el nombre y el pronombre para que el texto sea claro y no repetitivo.",
  ["Sé evitar repeticiones con pronombres.", "Sé detectar referentes ambiguos."],
  ["Un texto bien escrito alterna el nombre y el pronombre. Primero se nombra a la persona o cosa. Después se usa un pronombre mientras se entienda. Si pasa mucho tiempo, o aparece otra persona, se vuelve a usar el nombre.",
   "Por ejemplo: «Mateo salió temprano. Él caminó hasta la plaza. Allí encontró a Tomás. Mateo lo saludó». Se repite el nombre Mateo en la última oración porque apareció otro niño, Tomás, y él podría ser cualquiera.",
   "Una regla útil: usa el nombre al comenzar, usa el pronombre mientras el lector sepa quién es, y vuelve al nombre cuando cambies de personaje o haya duda. Así se evita la repetición y la confusión."],
  [("alternar", "usar una cosa y después otra"), ("nombre", "sustantivo que nombra a la persona"), ("pronombre", "palabra que reemplaza al nombre"), ("personaje", "persona o animal de un texto"), ("claridad", "que se entiende fácilmente")],
  [("Elegir cuándo volver al nombre", "Texto: «Mateo salió temprano. Él caminó hasta la plaza. Allí encontró a Tomás. ___ lo saludó». ¿Pones Él o Mateo?", ["Ahora hay dos niños.", "Él sería ambiguo.", "Pongo el nombre."], "Mateo"),
   ("Alternar", "Mejora: «Ema pintó. Ema usó rojo. Ema terminó».", ["Ema se repite.", "Dejo el nombre al comienzo.", "Uso ella después."], "«Ema pintó. Ella usó rojo y terminó»")],
  [("Repetir siempre el nombre.", "Suena pesado.", "Alterna con pronombre."), ("Usar siempre el pronombre aunque haya dos personajes.", "Se vuelve ambiguo.", "Repite el nombre.")],
  ([E("Un texto bien escrito, ¿repite siempre el mismo nombre o alterna nombre y pronombre?", "Alterna nombre y pronombre", "Así es claro y no repetitivo."),
    E("Si aparece un segundo personaje del mismo género, ¿es mejor volver al nombre? Responde sí o no.", "Sí", "Evita la confusión."),
    E("Primero se nombra al personaje y luego se usa…", "Un pronombre", "Reemplaza al nombre mientras se entienda.")],
   [E("En «Ema pintó. Ema usó rojo. Ema terminó», ¿cuántas veces se repite Ema?", "3", "Aparece en cada oración."),
    E("En «Lucas vio a Tomás. ___ lo saludó», ¿pones Él o Lucas para que sea claro?", "Lucas", "Él podría ser Tomás."),
    E("En «Rita entró. ___ saludó», ¿qué pones para no repetir el nombre, si solo hay una persona: Ella o Rita?", "Ella", "No hay duda y se evita repetir.")],
   [E("Completa para no repetir el nombre: «Ana abrió la puerta. ___ miró afuera». Elige Ella o Ana.", "Ella", "Solo hay un personaje."),
    E("Completa: «Pablo encontró a Hugo. ___ le dio un abrazo», pero fue Pablo quien abrazó. Elige Él o Pablo.", "Pablo", "Evita la ambigüedad."),
    E("Completa para no repetir el nombre: «Sol tiene un gato. ___ lo cuida». Elige Ella o Sol.", "Ella", "Solo hay una persona y ya se nombró.")],
   [E("En un texto el nombre «Mateo» se repite en las seis oraciones. ¿Cómo lo mejoras: usando pronombres donde sea claro o usando solo pronombres, sin nombrar nunca a Mateo?", "Usando pronombres donde sea claro", "Alterna nombre y pronombre."),
    E("Un niño usó «él» para dos personajes distintos. ¿Cómo corrige?", "Volviendo a usar el nombre", "Así queda claro a quién se refiere.")],
   [E("Texto: «Lola y Marta jugaron. ___ ganó». Lola ganó. ¿Qué pones: Ella o Lola?", "Lola", "Ella sería ambiguo."),
    E("Texto: «Don Raúl abrió la tienda. ___ saludó a los clientes. ___ vendió pan». Elige: él y él o Don Raúl y Don Raúl para que alterne y no sea pesado.", "Él y él", "Solo hay un personaje.")]),
  [E("Escribes un cuento sobre Pía y su perro Rufo: «Pía salió con Rufo. ___ ladraba mucho». Si quien ladraba era Rufo, ¿qué pones: Él o Rufo?", "Él", "Pía es femenina y Rufo masculino, así que él solo es Rufo.")],
  [E("¿Cuándo uso el nombre y cuándo el pronombre?", "Nombre al empezar o si hay duda; pronombre si es claro", "Así se alterna."),
   E("¿Un texto con solo nombres repetidos suena ligero o pesado?", "Pesado", "La repetición cansa."),
   E("Si hay dos personajes iguales, ¿conviene usar el nombre para evitar confusión? Responde sí o no.", "Sí", "El nombre es claro.")],
  ("Reescribe este texto alternando nombres y pronombres: «Daniela y Pedro fueron al campo. Daniela llevó una cesta. Pedro llevó una pelota. Daniela puso la cesta bajo un árbol. Pedro jugó con la pelota. Daniela comió una manzana». Mantén los nombres donde evitan confusión.", "«Daniela y Pedro fueron al campo. Ella llevó una cesta y él llevó una pelota. Daniela puso la cesta bajo un árbol. Pedro jugó con la pelota. Ella comió una manzana».", ["alterna nombre y pronombre", "no se confunde quién hace qué", "el texto es más ágil"], ["texto reescrito"], ["usar siempre el mismo nombre", "usar pronombres ambiguos"], "Lee tu versión a otra persona y comprueba que sepa quién hace cada acción."),
  "Cuenta algo que le pasó a un amigo sin repetir su nombre más de dos veces.",
  "Escribe un cuento de cuatro oraciones con dos personajes y alterna nombre y pronombre.")

L(OA21, 5,
  "Este cuaderno, lápiz y el párrafo de cada ejercicio.",
  "Aprenderé a revisar un párrafo para que sus ideas queden unidas con pronombres claros (cohesión).",
  ["Sé alternar nombre y pronombre.", "Sé detectar referentes ambiguos."],
  ["La cohesión es la unión entre las ideas de un texto. Una forma de lograr cohesión es usar pronombres que se refieran a lo ya dicho. Así el lector sigue el hilo del texto sin perderse.",
   "Para revisar la cohesión de un párrafo, haz tres preguntas. Primero, ¿cada pronombre tiene un referente claro? Segundo, ¿se repiten palabras sin necesidad? Tercero, ¿el pronombre concuerda en género y número con su referente?",
   "Si una respuesta es no, corrige. Puedes reemplazar una repetición por un pronombre, un pronombre ambiguo por un nombre, o un pronombre que no concuerda por el correcto. Después relee el párrafo completo."],
  [("cohesión", "unión entre las ideas de un texto"), ("hilo del texto", "lo que une las ideas de principio a fin"), ("concordancia", "coincidencia en género y número"), ("revisar", "leer de nuevo para mejorar"), ("párrafo", "grupo de oraciones sobre una idea")],
  [("Revisar la concordancia", "Párrafo: «Mi hermana tiene una bicicleta. Él la cuida mucho». ¿Qué falla?", ["Hermana es femenino.", "Él es masculino.", "Debe ser ella."], "«Él» no concuerda; debe ser «Ella»"),
   ("Revisar la repetición", "Párrafo: «El pájaro canta. El pájaro vuela. El pájaro come». ¿Qué corriges?", ["Se repite el pájaro.", "Uso él después de la primera vez."], "«El pájaro canta. Él vuela y come»")],
  [("Revisar solo la ortografía.", "Puede quedar un pronombre equivocado.", "Revisa también los pronombres."), ("Corregir un pronombre sin releer el párrafo.", "Puede aparecer otro error.", "Relee todo.")],
  ([E("La unión entre las ideas de un texto se llama…", "Cohesión", "Une las ideas."),
    E("Al revisar la cohesión, ¿reviso que cada pronombre tenga un referente claro? Responde sí o no.", "Sí", "Así no hay confusión."),
    E("¿Qué debe coincidir entre pronombre y referente: género y número o color?", "Género y número", "Deben concordar entre sí.")],
   [E("«Mi hermana tiene una bicicleta. Él la cuida mucho». ¿Qué pronombre falla?", "Él", "Hermana es femenino."),
    E("«El pájaro canta. El pájaro vuela. El pájaro come». ¿Qué problema tiene?", "Repite el pájaro", "Se repite sin necesidad."),
    E("«Ana y Sofía jugaron. Ella ganó». ¿Qué problema tiene?", "Es ambiguo", "Ella puede ser Ana o Sofía.")],
   [E("Corrige la concordancia: «Los gatos duermen. Ella ronronea». Escribe el pronombre correcto.", "Ellos", "Gatos es masculino plural."),
    E("Corrige la repetición en «Pía lee. Pía escribe». Escribe la segunda oración con un pronombre.", "Ella escribe", "Ella reemplaza a Pía."),
    E("Corrige la ambigüedad en «Lola y Marta rieron. Ella cantó». Si cantó Marta, escribe la segunda oración.", "Marta cantó", "El nombre aclara.")],
   [E("Un niño corrigió solo las tildes de un párrafo, pero quedaron tres pronombres ambiguos. ¿Qué le faltó?", "Revisar los pronombres", "Revisar la cohesión incluye pronombres."),
    E("Si en un párrafo hay muchas repeticiones del mismo nombre, ¿qué problema tiene: falta de ortografía o falta de cohesión?", "Falta de cohesión", "Las ideas no están bien unidas.")],
   [E("Revisa: «Tomás y Luis fueron al río. Él pescó un pez. Él lo soltó». Fue Tomás quien pescó y Luis quien lo soltó. Escribe la versión clara.", "Tomás pescó un pez. Luis lo soltó", "Cada nombre aclara quién actuó."),
    E("En «Mis tías llegaron. Él trajo pasteles», ¿qué pronombre falla y cuál lo corrige?", "Él; debe ser Ellas", "Tías es femenino plural y él es masculino singular.")]),
  [E("Un aviso dice: «Los alumnos de tercero harán una obra. Ella será el viernes». ¿A qué sustantivo debería referirse «ella» para tener sentido: a la obra o a los alumnos?", "A la obra", "La obra será el viernes y obra es femenino singular.")],
  [E("¿Qué es la cohesión de un texto?", "La unión entre sus ideas", "Hace que se lea como un todo."),
   E("¿Un pronombre que no concuerda es un error de cohesión? Responde sí o no.", "Sí", "No remite bien a su referente."),
   E("Después de corregir un párrafo, ¿qué hago: releerlo completo o entregarlo?", "Releerlo completo", "Así compruebo que quedó bien.")],
  ("Revisa este párrafo: «Luna tiene un gato llamado Bruno. Luna cuida a Bruno cada día. Él duerme en su cama. Ellas juegan juntos todas las tardes. Él salta sobre la mesa». Corrige repeticiones, pronombres que no concuerdan y ambigüedades. Escribe tu versión y señala dos cambios.", "«Luna tiene un gato llamado Bruno. Lo cuida cada día. Bruno duerme en su cama. Los dos juegan juntos todas las tardes. A veces él salta sobre la mesa». Cambios: reemplazar la repetición por «lo»; cambiar «Ellas» por «Los dos».", ["corrige la repetición", "corrige la concordancia", "explica dos cambios"], ["párrafo revisado", "dos cambios anotados"], ["dejar «Ellas»", "no corregir la repetición de Luna y Bruno"], "Pide a otra persona que lea tu versión y diga si fluye."),
  "Elige un párrafo tuyo y revisa sus pronombres con las tres preguntas.",
  "Escribe un párrafo con tres errores de cohesión y pide a otra persona que los encuentre.")

# ------------------------------------------------------------------ OA 22
L(OA22, 1,
  "Este cuaderno, lápiz y los textos con errores de cada ejercicio.",
  "Aprenderé a usar la mayúscula al empezar una oración y al escribir nombres propios, y el punto al terminarla, para que el lector entienda.",
  ["Sé escribir oraciones.", "Sé reconocer sustantivos."],
  ["La mayúscula se usa al empezar una oración y al escribir sustantivos propios, es decir, nombres de personas, mascotas, lugares y países: Ana, Luna, Valparaíso, Chile. Los días y los meses se escriben con minúscula: lunes, mayo.",
   "El punto marca el final de una oración. Sin puntos y mayúsculas, el texto se lee como una sola cadena y puede confundir. Compara «La señora Rosa compró una rosa»: Rosa con mayúscula es el nombre de la señora, y rosa con minúscula es la flor.",
   "Al revisar, pregúntate: ¿empieza con mayúscula cada oración? ¿llevan mayúscula los nombres propios? ¿terminé cada oración con punto? Estos pequeños signos ayudan a que otros entiendan tu mensaje."],
  [("mayúscula", "letra grande que se usa al comienzo de una oración y en nombres propios"), ("nombre propio", "nombre de una persona, mascota o lugar único"), ("punto", "signo que cierra una oración"), ("oración", "grupo de palabras con sentido completo"), ("comprensión", "entender lo que se lee")],
  [("Corregir mayúsculas y punto", "Corrige: «mi perro luna vive en valparaíso».", ["La oración empieza con mayúscula.", "Luna es nombre de mi perro.", "Valparaíso es un lugar.", "Falta el punto."], "Mi perro Luna vive en Valparaíso."),
   ("Mayúscula que cambia el sentido", "¿Qué diferencia hay entre «Rosa» y «rosa» en «La señora Rosa compró una rosa»?", ["Rosa con mayúscula es un nombre.", "Rosa con minúscula es una flor."], "Rosa es el nombre de la señora; rosa es la flor")],
  [("Escribir los días con mayúscula: «El Lunes».", "Los días se escriben con minúscula.", "Escribe «el lunes»."), ("Olvidar el punto final.", "No se sabe dónde termina.", "Cierra cada oración con punto.")],
  ([E("En Lenguaje: ¿Con qué letra empieza una oración: mayúscula o minúscula?", "Mayúscula", "Toda oración empieza con mayúscula."),
    E("¿Con qué letra se escribe el nombre «Ana»?", "Mayúscula", "Es un nombre propio."),
    E("¿Qué signo cierra una oración: el punto o la coma?", "El punto", "El punto marca el final.")],
   [E("¿Cuál lleva mayúscula: «chile» o «el pan»?", "Chile", "Es el nombre de un país."),
    E("¿Los días de la semana, como lunes, se escriben con mayúscula o con minúscula?", "Con minúscula", "No son nombres propios."),
    E("En «La señora Rosa compró una rosa», ¿cuál «rosa» es una flor?", "La que está en minúscula", "La flor no es un nombre propio.")],
   [E("Corrige: «mi gato pelusa duerme». Escribe la oración correcta.", "Mi gato Pelusa duerme.", "Mayúscula inicial, nombre propio y punto."),
    E("Corrige: «ayer fuimos a santiago». Escribe la oración correcta.", "Ayer fuimos a Santiago.", "Mayúscula inicial, lugar y punto."),
    E("Corrige: «el sábado viene tomás». Escribe la oración correcta.", "El sábado viene Tomás.", "Sábado va en minúscula y Tomás en mayúscula.")],
   [E("Un niño escribió «Mañana voy al Parque con Sofía». ¿Qué palabra tiene mayúscula de más?", "Parque", "Parque no es un nombre propio aquí."),
    E("¿Por qué «Pilar» y «pilar» pueden significar cosas distintas?", "Una es un nombre y la otra una cosa", "La mayúscula marca el nombre propio.")],
   [E("Corrige el texto: «me llamo clara. vivo en valdivia. mi perro se llama toby». Escribe cuántas mayúsculas necesita en total.", "6", "Son Me, Clara, Vivo, Valdivia, Mi y Toby."),
    E("¿Cuántos puntos necesita el texto «me llamo clara vivo en valdivia mi perro se llama toby»?", "3", "Tiene tres oraciones.")]),
  [E("Un cartel dice: «el lunes habrá feria en la plaza de talca». ¿Cuál palabra debe llevar mayúscula inicial y cuál es nombre de lugar?", "El y Talca", "La oración empieza con El y Talca es una ciudad.")],
  [E("¿Cuándo uso mayúscula?", "Al empezar una oración y en nombres propios", "Así se marca el inicio y el nombre."),
   E("¿Dónde pongo el punto?", "Al final de la oración", "Cierra la idea."),
   E("¿El mes «mayo» lleva mayúscula en medio de una oración? Responde sí o no.", "No", "Los meses van con minúscula.")],
  ("Corrige este texto: «hola me llamo diego vivo en puerto montt el domingo fui con mi perro canela al parque». Escribe el texto correcto con mayúsculas y puntos. Luego marca los nombres propios.", "«Hola, me llamo Diego. Vivo en Puerto Montt. El domingo fui con mi perro Canela al parque». Nombres propios: Diego, Puerto Montt, Canela.", ["mayúscula inicial en cada oración", "mayúscula en nombres propios", "puntos al final de cada oración"], ["texto corregido", "nombres propios marcados"], ["olvidar los puntos", "escribir domingo con mayúscula"], "Pide a otra persona que lea tu texto y diga dónde se detiene."),
  "Busca en un libro tres nombres propios y di por qué llevan mayúscula.",
  "Escribe cinco oraciones sobre tu semana, con mayúscula y punto bien usados.")

L(OA22, 2,
  "Este cuaderno, lápiz y los textos de cada ejercicio.",
  "Aprenderé a diferenciar punto seguido, punto aparte y punto final, y a usar el punto aparte para organizar un texto en párrafos.",
  ["Sé usar mayúsculas y punto.", "Sé qué es un párrafo."],
  ["Hay tres usos del punto. El punto seguido separa oraciones dentro de un mismo párrafo y se sigue escribiendo en la misma línea. El punto aparte cierra un párrafo y se sigue en la línea de abajo. El punto final cierra todo el texto.",
   "Usa punto seguido cuando la idea continúa. Usa punto aparte cuando cambia el tema o la idea principal. En un texto sobre una mascota, un párrafo puede describirla y otro puede contar qué le gusta hacer.",
   "Después de punto seguido o aparte, la oración siguiente empieza con mayúscula. Si pones puntos donde no corresponde, el texto se corta. Si no pones, se pega. Lee tu texto en voz alta y haz una pausa donde pongas cada punto."],
  [("punto seguido", "punto que separa oraciones del mismo párrafo"), ("punto aparte", "punto que termina un párrafo"), ("punto final", "punto que termina el texto"), ("organización", "orden en las partes de un texto"), ("pausa", "momento de silencio al leer")],
  [("Elegir el punto", "Texto: «Mi gato se llama Bruno. Es negro. Le gusta dormir». ¿Qué punto va entre «Bruno» y «Es»?", ["La idea continúa.", "Hablan del mismo gato.", "Es punto seguido."], "Punto seguido"),
   ("Marcar el cambio de idea", "Texto: «Mi gato duerme mucho. Mi hermana juega fútbol». ¿Dónde pondrías punto aparte?", ["La primera oración habla del gato.", "La segunda cambia a la hermana.", "El punto aparte va después de la primera."], "Después de «Mi gato duerme mucho.»")],
  [("Poner punto aparte tras cada oración.", "Las ideas del mismo tema se separan.", "Usa punto seguido si sigue la idea."), ("Olvidar el punto final.", "El texto no cierra.", "Termina con punto final.")],
  ([E("¿Qué punto se usa entre oraciones de un mismo párrafo: seguido o aparte?", "Seguido", "Las ideas siguen en la misma línea."),
    E("¿Qué punto cierra un párrafo: seguido o aparte?", "Aparte", "Se sigue en otra línea."),
    E("¿Qué punto cierra todo el texto: el final o el seguido?", "El final", "Marca el término del texto.")],
   [E("En «Hoy hice galletas. Usé harina y azúcar. Después fui a jugar», ¿entre «galletas» y «Usé» va punto seguido o aparte?", "Seguido", "Sigue el tema de las galletas."),
    E("En el mismo texto, ¿entre «azúcar» y «Después» conviene punto aparte o seguido? El tema cambia a jugar.", "Aparte", "Cambia el tema."),
    E("Después de un punto aparte, ¿la siguiente línea empieza con mayúscula o minúscula?", "Mayúscula", "Empieza una nueva oración.")],
   [E("Mi perro corre. Mi perro salta. Mi perro duerme. ¿Qué punto va entre estas oraciones del mismo tema?", "Punto seguido", "Todas hablan del perro."),
    E("«Fui al zoológico. Vi un oso. Mañana tengo prueba». ¿Dónde va el punto aparte?", "Después de «Vi un oso.»", "Allí cambia el tema a la prueba."),
    E("¿Cuántos puntos finales tiene un texto de dos párrafos?", "1", "El punto final cierra el texto, no cada párrafo.")],
   [E("Un niño puso punto aparte después de cada oración, aunque hablaban de lo mismo. ¿Qué punto debía usar en esos casos?", "Punto seguido", "Las ideas siguen en el mismo párrafo."),
    E("Un texto sin ningún punto aparte, ¿es fácil de ordenar? Responde sí o no.", "No", "No se ve el cambio de idea.")],
   [E("Lee: «La playa es linda. Tiene arena fina. Las olas son grandes. Mi curso comerá helado. Será el viernes». ¿Dónde va el punto aparte?", "Después de «Las olas son grandes.»", "Después se cambia al tema de comer helado."),
    E("Cuenta: en «Mi gato es suave. Le gusta la leche. Mi perro es grande. Corre mucho», ¿cuántas oraciones tiene el segundo párrafo si separas gato y perro?", "2", "El segundo párrafo tiene las oraciones del perro.")]),
  [E("Preparas una carta con dos temas: tu escuela y tu cumpleaños. Entre el último punto del primer tema y el segundo tema, ¿pones punto aparte o seguido?", "Punto aparte", "Cambia el tema.")],
  [E("¿Cuándo uso punto aparte?", "Cuando cambia la idea", "Marca un nuevo párrafo."),
   E("¿Qué letra va después de un punto?", "Mayúscula", "Empieza otra oración."),
   E("¿Cuál punto marca el final de todo el texto?", "El punto final", "Cierra el texto completo.")],
  ("Pon los puntos en este texto, de modo que tenga dos párrafos: «Mi curso fue al museo vimos un dinosaurio gigante también había un mapa antiguo al día siguiente hicimos un dibujo usamos lápices de colores». Escribe el texto con puntos seguidos, un punto aparte y un punto final. Escribe una frase que diga dónde y por qué pusiste cada tipo de punto.", "«Mi curso fue al museo. Vimos un dinosaurio gigante. También había un mapa antiguo. Al día siguiente hicimos un dibujo. Usamos lápices de colores». Punto aparte después de «antiguo» porque cambia el tema.", ["pone puntos seguidos entre oraciones del mismo tema", "pone un punto aparte donde cambia el tema", "explica sus decisiones"], ["texto con dos párrafos", "frase de explicación"], ["un punto aparte tras cada oración", "olvidar el punto final"], "Lee tu texto en voz alta y comprueba que las pausas se oigan."),
  "Observa un texto corto y marca el punto aparte.",
  "Escribe dos párrafos sobre tu día y usa los tres tipos de punto.")

L(OA22, 3,
  "Este cuaderno, lápiz y las palabras de cada ejercicio.",
  "Aprenderé a formar el plural de las palabras que terminan en z, cambiando la z por ces.",
  ["Sé formar plurales regulares.", "Conozco la letra z y la letra c."],
  ["Para formar el plural de las palabras que terminan en z, se cambia la z por c y se agrega es. Lápiz es lápices, luz es luces, pez es peces y vez es veces. No se escribe «lápizes» ni «luzes».",
   "Otras palabras que siguen la misma regla son nariz (narices), cruz (cruces), feliz (felices), voz (voces), lombriz (lombrices), actriz (actrices) y capaz (capaces). La razón es que la z casi no se escribe antes de e o i en español.",
   "Aunque «luces» se pronuncie con s, se escribe con c. Si dudas, cambia la z por c. También puedes hacer el camino contrario: si ves «narices», piensa que su singular es nariz."],
  [("plural", "más de uno"), ("singular", "uno solo"), ("terminación", "letras finales de una palabra"), ("lápiz", "instrumento para escribir"), ("regla", "forma que se repite en muchas palabras")],
  [("Formar un plural", "Escribe el plural de «luz».", ["Termina en z.", "Cambio la z por c.", "Agrego es: luces."], "Luces"),
   ("Buscar el singular", "¿Cuál es el singular de «peces»?", ["Peces termina en ces.", "Quito es y cambio la c por z."], "Pez")],
  [("Escribir «lápizes».", "La z se cambia por c antes de es.", "Escribe lápices."), ("Escribir «veses».", "El plural conserva el sonido pero se escribe con c.", "Escribe veces.")],
  ([E("¿Cuál es el plural de «luz»: luces o luzes?", "Luces", "La z cambia a c."),
    E("¿Cuál es el plural de «pez»: peces o pezes?", "Peces", "La z cambia a c."),
    E("¿Cuál es el singular de «lápices»: lápiz o lápis?", "Lápiz", "Termina en z.")],
   [E("Escribe el plural de «vez».", "Veces", "Se cambia la z por c y se agrega es."),
    E("Escribe el plural de «nariz».", "Narices", "La z cambia a c."),
    E("Escribe el singular de «cruces».", "Cruz", "Se vuelve a la z.")],
   [E("Completa con el plural de «lápiz»: «Compré tres ___ de colores».", "Lápices", "La z se cambia por c."),
    E("Completa con el plural de «feliz»: «Los niños están ___».", "Felices", "La z se cambia por c."),
    E("Completa con el plural de «voz»: «En el coro se oyen muchas ___».", "Voces", "La z se cambia por c.")],
   [E("Un niño escribió «Vi dos peces y tres lombrizes». ¿Qué palabra está mal escrita y cómo se escribe bien?", "Lombrizes; lombrices", "La z cambia a c."),
    E("¿Por qué el plural de «actriz» no es «actrizes»?", "Porque la z se cambia por c", "Esa es la regla.")],
   [E("Escribe el plural de «capaz» y úsalo: «Somos ___ de leer». Escribe solo el plural.", "Capaces", "La z cambia a c."),
    E("Lee: «Las veces que fuimos, vimos muchas cruces». Escribe el singular de las dos palabras con ces, en orden.", "Vez y cruz", "Se cambia ces por z.")]),
  [E("Un cartel dice: «Aquí se venden lapizes». ¿Cómo debe decir?", "Lápices", "La z cambia a c.")],
  [E("¿Cuál es la regla del plural de las palabras en z?", "Se cambia la z por c y se agrega es", "Es la regla del plural."),
   E("¿Cuál es el plural de «pez»?", "Peces", "La z cambia a c."),
   E("¿Se escribe «luzes»? Responde sí o no.", "No", "Se escribe luces.")],
  ("Escribe el plural de estas palabras: lápiz, luz, pez, vez, nariz, cruz. Luego escribe una oración con tres de los plurales que formaste. Comprueba que ninguna lleve zes.", "Lápices, luces, peces, veces, narices, cruces. Oración: «Los niños dibujaron peces con lápices de colores bajo las luces de la sala».", ["forma bien seis plurales", "escribe una oración con tres", "no usa zes"], ["lista de plurales", "oración con tres plurales"], ["escribir lápizes", "no cambiar la z por c"], "Revisa con otra persona que no haya ningún «zes»."),
  "Busca en tu casa tres cosas cuyo nombre termine en z y escribe su plural.",
  "Escribe seis plurales más: antifaz, actriz, lombriz, feliz, voz, capaz.")

L(OA22, 4,
  "Este cuaderno, lápiz y las palabras de cada ejercicio.",
  "Aprenderé a escribir bien palabras con ge, gi, je y ji, usando las familias de palabras y algunas reglas.",
  ["Sé que ge y gi suenan como je y ji.", "Sé leer familias de palabras."],
  ["El sonido «je» se escribe a veces je y a veces ge, y el sonido «ji» se escribe a veces ji y a veces gi. Para no equivocarte, observa familias de palabras. Si una palabra de la familia lleva j, casi siempre las otras también: viaje, viajar, viajero. Si lleva g, igual: página, paginar. Hay unas pocas palabras de familia que no siguen esto, así que ante la duda usa el diccionario.",
   "Una regla útil: las palabras que terminan en -aje se escriben con j. Ejemplos: viaje, mensaje, paisaje, equipaje. Otra regla: los verbos terminados en -ger y -gir (en infinitivo) se escriben con g, como elegir, recoger y proteger. Hay excepciones, como tejer y crujir, que se aprenden aparte.",
   "Algunas palabras se aprenden de memoria: gente, gigante, girasol y gelatina llevan g; jirafa, jinete y ejemplo llevan j. Cuando dudes, busca la palabra en el diccionario o piensa en su familia."],
  [("familia de palabras", "palabras que comparten una misma raíz"), ("terminación -aje", "final de palabras como viaje y mensaje"), ("verbo", "palabra que dice acción"), ("excepción", "caso que no sigue la regla"), ("diccionario", "libro para comprobar cómo se escribe una palabra")],
  [("Usar la regla -aje", "Completa con g o j: «mensa__e».", ["Termina en -aje.", "Las palabras con -aje llevan j."], "Mensaje con j"),
   ("Usar la familia", "¿Cómo se escribe «viajero»: con j o con g?", ["Viaje lleva j.", "Viajero es de su familia."], "Con j: viajero")],
  [("Escribir «viage».", "Las palabras terminadas en -aje llevan j.", "Escribe viaje."), ("Escribir «elejir».", "Elegir es un verbo en -gir y lleva g.", "Escribe elegir.")],
  ([E("¿Cómo se escribe: viaje o viage?", "Viaje", "Las palabras en -aje llevan j."),
    E("¿Cómo se escribe: gente o jente?", "Gente", "Se escribe con g."),
    E("¿Cómo se escribe: jirafa o girafa?", "Jirafa", "Se escribe con j.")],
   [E("Completa con g o j: «mensa__e».", "J", "Termina en -aje."),
    E("¿Cómo se escribe «viajar»: con j o con g?", "Con j", "Es de la familia de viaje."),
    E("Completa con g o j: «ele__ir».", "G", "Los verbos en -gir llevan g.")],
   [E("Completa con g o j: «pa__ina» (hoja de un libro).", "G", "Se escribe página con g."),
    E("Completa con g o j: «__inete» (persona que monta a caballo).", "J", "Se escribe jinete con j."),
    E("Completa con g o j: «paisa__e».", "J", "Termina en -aje.")],
   [E("¿Cómo se escribe la palabra de la familia de «mensaje» que nombra a quien lleva mensajes: mensajero o mensagero?", "Mensajero", "Mantiene la j de mensaje."),
    E("¿Por qué «elegir» lleva g y no j?", "Porque es un verbo terminado en -gir", "Esa es la regla.")],
   [E("Escribe con g o j las palabras que faltan: «Hicimos un ___ en tren (via__e) y cada uno llevó su ___ (equipa__e)». Escribe las dos palabras.", "Viaje y equipaje", "Ambas terminan en -aje."),
    E("Elige la correcta: «recojer» o «recoger».", "Recoger", "Los verbos en -ger llevan g.")]),
  [E("Un cartel de un terminal dice: «Guarde su equipa__e». ¿Con qué letra se completa: j o g?", "J", "Equipaje termina en -aje.")],
  [E("¿Con qué letra se escriben las palabras que terminan en -aje?", "Con j", "Es la regla de -aje."),
   E("¿Con qué letra se escriben los verbos terminados en -gir, como elegir?", "Con g", "Es la regla de -gir."),
   E("¿Qué ayuda a escribir bien una palabra: pensar en su familia o adivinar?", "Pensar en su familia", "Las familias conservan la letra.")],
  ("Completa las palabras con g o j y explica la regla o la familia que usaste: via__e, mensa__ero, ele__ir, __irasol, pa__ina, __inete. Escribe cada palabra completa y una frase para la última palabra.", "Viaje (-aje), mensajero (familia de mensaje), elegir (-gir), girasol, página, jinete. Frase: «El jinete monta un caballo».", ["completa seis palabras", "usa la regla o la familia", "escribe una frase"], ["seis palabras", "una frase"], ["escribir viage", "elejir"], "Comprueba las palabras con un diccionario."),
  "Busca en un libro tres palabras que terminen en -aje.",
  "Escribe seis palabras con g y seis con j.")

L(OA22, 5,
  "Este cuaderno, lápiz y las palabras de cada ejercicio.",
  "Aprenderé a escribir los diminutivos terminados en -cito y -cita, que se escriben con c.",
  ["Sé qué es un diminutivo.", "Sé que ce y ci suenan como s."],
  ["Un diminutivo es una palabra que indica algo pequeño o querido. Se forma con terminaciones como -ito, -ita, -cito o -cita. Casa es casita y gato es gatito. Las palabras que terminan en a o en o usan -ito o -ita.",
   "Las palabras que terminan en n, en r o en e suelen usar -cito o -cita: corazón es corazoncito, camión es camioncito, canción es cancioncita, mujer es mujercita, parque es parquecito y madre es madrecita. Se escribe con c, no con s ni con z.",
   "Cuidado con los errores como «corazonsito» o «parquesito». En los diminutivos, la terminación -cito suena con s, pero se escribe con c. Para revisar, pregúntate si la palabra base termina en n, r o e y entonces usa -cito o -cita."],
  [("diminutivo", "palabra que indica algo pequeño o querido"), ("terminación", "letras del final de una palabra"), ("-cito, -cita", "terminaciones de diminutivo con c"), ("palabra base", "la palabra de la que sale el diminutivo"), ("ortografía", "forma correcta de escribir")],
  [("Formar un diminutivo con -cito", "Forma el diminutivo de «camión».", ["Termina en n.", "Uso -cito.", "Camión + cito = camioncito."], "Camioncito"),
   ("Formar un diminutivo con -ita", "Forma el diminutivo de «casa».", ["Termina en a.", "Uso -ita.", "Casa pasa a casita."], "Casita")],
  [("Escribir «corazonsito».", "La terminación se escribe con c.", "Escribe corazoncito."), ("Usar -cito en una palabra terminada en o.", "En o se usa -ito.", "Escribe gatito.")],
  ([E("¿Qué indica un diminutivo: algo pequeño o algo grande?", "Algo pequeño", "Eso indica el diminutivo."),
    E("¿Cuál es el diminutivo de «casa»: casita o casacita?", "Casita", "Termina en a y usa -ita."),
    E("¿Cuál se escribe bien: «camioncito» o «camionsito»?", "Camioncito", "La terminación se escribe con c.")],
   [E("Escribe el diminutivo de «canción».", "Cancioncita", "Termina en n y usa -cita."),
    E("Escribe el diminutivo de «parque».", "Parquecito", "Termina en e y usa -cito."),
    E("Escribe el diminutivo de «gato».", "Gatito", "Termina en o y usa -ito.")],
   [E("Completa: «Mi ___ (madre) me cuenta cuentos». Escribe el diminutivo.", "Madrecita", "Termina en e y usa -cita."),
    E("Completa: «Vi un ___ (ratón) en el cuento». Escribe el diminutivo.", "Ratoncito", "Termina en n y usa -cito."),
    E("Completa: «La ___ (mujer) del cuento era muy simpática». Escribe el diminutivo.", "Mujercita", "Termina en r y usa -cita.")],
   [E("Un niño escribió «jardinsito». ¿Cómo se escribe bien el diminutivo de jardín?", "Jardincito", "La terminación se escribe con c."),
    E("¿Por qué «perrito» no lleva c?", "Porque perro termina en o", "Esa terminación usa -ito.")],
   [E("Clasifica estas palabras según su diminutivo: casa, corazón, gato, parque. Escribe cuáles usan -cito o -cita.", "Corazón y parque", "Terminan en n y e."),
    E("Escribe el diminutivo de «coche».", "Cochecito", "Termina en e y usa -cito.")]),
  [E("En una librería hay un cartel con un error: «Cancionsitas infantiles». ¿Cómo se escribe correctamente?", "Cancioncitas infantiles", "La terminación se escribe con c.")],
  [E("¿Cómo se escribe el diminutivo de «camión»?", "Camioncito", "Termina en n y usa -cito."),
   E("¿Con qué letra se escribe -cito?", "Con c", "No se escribe con s ni con z."),
   E("¿Palabras terminadas en o usan -ito o -cito?", "-ito", "Gato pasa a gatito.")],
  ("Forma los diminutivos de estas palabras y úsalos en una oración cada uno: madre, camión, parque. Subraya la terminación -cito o -cita en cada diminutivo. Luego escribe un cartel de tienda con un diminutivo de tu elección.", "Madrecita: «Mi madrecita cocina». Camioncito: «El camioncito es rojo». Parquecito: «Voy al parquecito». Cartel: «Cancioncitas para niños».", ["escribe tres diminutivos con c", "usa cada uno en una oración", "subraya la terminación"], ["tres diminutivos", "tres oraciones", "cartel"], ["escribir con s", "usar -cito con palabras en o"], "Léele tus oraciones a otra persona y revisen la ortografía."),
  "Busca dos diminutivos que escuches hoy y escribe cómo se escriben.",
  "Escribe cuatro diminutivos con -cito o -cita y cuatro con -ito o -ita.")

L(OA22, 6,
  "Este cuaderno, lápiz y los textos de cada ejercicio.",
  "Aprenderé a usar la coma en una enumeración para separar los elementos de una lista dentro de una oración.",
  ["Sé usar mayúsculas y puntos.", "Sé que una oración tiene sentido completo."],
  ["Una enumeración es una lista de cosas, personas o ideas dentro de una oración. «Compré manzanas, peras, uvas y plátanos» es una enumeración. Los elementos se separan con comas, y antes del último se usa y, sin coma.",
   "La coma indica una pausa breve. Sin comas, una lista se puede confundir: «Invité a mi tía Rosa, a mi primo y a Pía» tiene tres personas, pero si se escribe sin comas puede parecer otra cosa. Las comas ayudan a ver cuántos elementos hay.",
   "También se enumeran adjetivos o acciones: «El gato es negro, suave y juguetón». «Llegué, saludé y me senté». Recuerda: coma entre los elementos, sin coma antes de la y final, y punto al terminar la oración."],
  [("enumeración", "lista de elementos dentro de una oración"), ("coma", "signo que marca una pausa breve"), ("elemento", "cada parte de una lista"), ("y", "palabra que une el último elemento de la lista"), ("pausa", "momento breve de silencio al leer")],
  [("Poner comas en una lista", "Pon comas: «Compré manzanas peras uvas y plátanos».", ["Hay cuatro elementos.", "Pongo coma entre los tres primeros.", "Antes de y no pongo coma."], "Compré manzanas, peras, uvas y plátanos."),
   ("Contar elementos", "¿Cuántos elementos tiene «Llegué, saludé y me senté»?", ["Veo tres acciones.", "Están separadas por coma y por y."], "3")],
  [("Poner coma antes de la y final.", "En una lista, el último elemento se une con y, sin coma.", "Escribe «peras y plátanos»."), ("No usar comas en una lista.", "Es difícil saber cuántos elementos hay.", "Separa los elementos con comas.")],
  ([E("Una lista de cosas dentro de una oración se llama…", "Enumeración", "Es una lista de elementos."),
    E("¿Qué signo separa los elementos de una enumeración?", "La coma", "Marca una pausa breve."),
    E("Antes de la «y» final en una lista, ¿se pone coma? Responde sí o no.", "No", "La y une el último elemento.")],
   [E("¿Cuántos elementos hay en «Compré pan, leche y queso»?", "3", "Son pan, leche y queso."),
    E("En «Mi mochila tiene cuadernos, lápices, una regla y un estuche», ¿cuántas comas hay?", "2", "Hay una coma tras cuadernos y otra tras lápices."),
    E("¿Dónde falta la coma en «Voy al parque a la plaza y a la feria»?", "Después de parque", "Allí termina el primer elemento.")],
   [E("Pon comas: «Mi gato es negro suave y juguetón».", "Mi gato es negro, suave y juguetón.", "Una coma separa negro y suave."),
    E("Pon comas: «Ayer comí arroz pollo ensalada y fruta».", "Ayer comí arroz, pollo, ensalada y fruta.", "Tres elementos separados por coma y el último con y."),
    E("Pon comas: «Llegué saludé y me senté».", "Llegué, saludé y me senté.", "Una coma entre llegué y saludé.")],
   [E("Un niño escribió «Compré peras, uvas, y plátanos». ¿Qué coma sobra?", "La que está antes de y", "Antes de y final no se pone coma."),
    E("¿Por qué ayudan las comas en «Invité a Ana, a Luis y a Pía»?", "Porque muestran que son tres personas", "Marcan cada elemento.")],
   [E("Escribe una oración con tres animales de esta lista: gato, perro, loro, pez. Debe tener comas y una y. Escribe cuántas comas lleva.", "1", "Con tres elementos hay una coma y una y."),
    E("Cuenta las comas de «En el patio hay columpios, un tobogán, una barra, un subibaja y una cancha».", "3", "Hay cinco elementos: tres comas y una y.")]),
  [E("Escribes una lista de útiles para tu mochila: «cuaderno lápiz goma y regla». ¿Cuántas comas debes poner?", "2", "Hay cuatro elementos; las comas van entre los tres primeros.")],
  [E("¿Qué es una enumeración?", "Una lista de elementos en una oración", "Se separan con comas."),
   E("¿Dónde se pone la coma en una lista: entre los elementos o después del punto?", "Entre los elementos", "Separa cada elemento."),
   E("En una lista de tres elementos, ¿cuántas comas hay?", "1", "Una coma y una y.")],
  ("Escribe una oración con una enumeración sobre cada tema: a) tres frutas que te gustan; b) cuatro cosas que hay en tu sala de clases; c) tres acciones que haces al llegar a casa. Usa comas y la y final. Subraya los elementos de cada lista.", "a) Me gustan las manzanas, las peras y las uvas. b) En mi sala hay mesas, sillas, un pizarrón y un mapa. c) Llego, saludo y me lavo las manos.", ["tres oraciones con enumeración", "comas bien usadas", "sin coma antes de y"], ["tres oraciones con listas subrayadas"], ["coma antes de y final", "olvidar las comas"], "Lee tus oraciones en voz alta y haz una pausa en cada coma."),
  "Escribe una lista de compras con cuatro elementos dentro de una oración.",
  "Escribe tres oraciones con enumeraciones y cuenta los elementos de cada una.")
